const pharmacies = [
  {id:'a',priority:'A',name:'Linden-Apotheke',city:'Bad Vilbel',duration:45,lat:25,top:31},
  {id:'b',priority:'A',name:'Apotheke am Markt',city:'Frankfurt',duration:30,lat:43,top:45},
  {id:'c',priority:'B',name:'Mainbogen-Apotheke',city:'Hanau',duration:30,lat:66,top:29},
  {id:'d',priority:'B',name:'Sonnen-Apotheke',city:'Offenbach',duration:30,lat:78,top:57},
  {id:'e',priority:'A',name:'Schloss-Apotheke',city:'Darmstadt',duration:45,lat:46,top:76},
  {id:'f',priority:'C',name:'Rosen-Apotheke',city:'Mainz',duration:30,lat:18,top:64},
  {id:'g',priority:'B',name:'Kur-Apotheke',city:'Wiesbaden',duration:30,lat:29,top:78},
  {id:'h',priority:'A',name:'Kinzig-Apotheke',city:'Gelnhausen',duration:30,lat:86,top:22}
];
let route = JSON.parse(localStorage.getItem('ea-route') || '["a","b","c","d"]');
let editing = false;
let activeView = 'today';
const app = document.getElementById('app');
const byId = id => pharmacies.find(p => p.id === id);
const save = () => localStorage.setItem('ea-route', JSON.stringify(route));
const nav = p => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${p.name}, ${p.city}`)}`;
const times = () => {let minute=9*60;return route.map(id=>{const p=byId(id),start=`${String(Math.floor(minute/60)).padStart(2,'0')}:${String(minute%60).padStart(2,'0')}`;minute+=p.duration+22;return {...p,start}})};
function shell(content){return `<div class="shell"><aside><div class="brand"><span>e</span><div><b>Engelhard</b><small>Routenplaner</small></div></div><nav>${[['today','Heute','⌂'],['round','Verkaufsrunde','▦'],['pharmacies','Apotheken','✚'],['settings','Einstellungen','⚙']].map(([id,label,icon])=>`<button data-view="${id}" class="${activeView===id?'active':''}"><i>${icon}</i>${label}</button>`).join('')}</nav><div class="demo">POC · Synthetische Daten</div></aside><main>${content}</main></div>`}
function header(kicker,title,actions=''){return `<header><div><span class="kicker">${kicker}</span><h1>${title}</h1></div><div class="header-actions">${actions}<button class="avatar">AJ</button></div></header>`}
function today(){const stops=times(),drive=96+Math.max(0,route.length-4)*18,total=stops.reduce((s,p)=>s+p.duration,0)+drive;return shell(`${header('MONTAG · 3. AUGUST','Guten Morgen, Alex.',`<button id="optimize" class="soft">✦ Optimieren</button><button id="edit" class="primary">${editing?'Fertig':'Plan anpassen'}</button>`)}<section class="day-summary"><div><span class="live"><i></i> Dein optimaler Tag</span><h2>${route.length} Apotheken für heute</h2><p>Wir haben Nähe, Priorität und Besuchsdauer für dich ausbalanciert.</p></div><div class="summary-metrics"><b>${Math.floor(total/60)} h ${total%60} min<small>Gesamtdauer</small></b><b>74 km<small>Strecke</small></b><b>16:18<small>Zurück zu Hause</small></b></div></section><div class="workspace"><section class="map-card"><div class="map-top"><div><b>Rhein-Main Ost</b><span>Live-Tagesroute</span></div><button class="map-action">⌖ Zentrieren</button></div><div class="map-surface"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M8 70 C18 58 18 38 30 34 S46 52 57 40 S72 20 90 30"/><path class="minor" d="M5 30 C30 48 55 25 94 67"/><path class="minor" d="M26 8 C34 30 65 64 74 92"/></svg><span class="home" style="left:9%;top:69%">⌂</span>${stops.map((p,i)=>`<span class="map-pin ${i===0?'current':''}" style="left:${p.lat}%;top:${p.top}%">${i+1}</span>`).join('')}<div class="map-legend"><b>74 km</b><span>1 h 36 min Fahrzeit</span></div></div></section><section class="plan-card"><div class="plan-head"><div><span class="kicker">TAGESPLAN</span><h3>Empfohlene Reihenfolge</h3></div><span class="quality">Optimal</span></div><div id="stop-list">${stops.map((p,i)=>`<article class="stop" draggable="${editing}" data-id="${p.id}"><span class="grip">${editing?'⠿':i+1}</span><div class="stop-time">${p.start}</div><div class="stop-copy"><b>${p.name}</b><span>${p.city} · ${p.duration} Min.</span></div><a href="${nav(p)}" target="_blank" title="Navigation zu ${p.name}" aria-label="Navigation zu ${p.name}">⌖</a>${editing?'<button class="remove" title="Entfernen">×</button>':''}</article>`).join('')}</div>${editing?'<button id="add" class="add">＋ Apotheke hinzufügen</button>':'<p class="hint">Tippe auf „Plan anpassen“, um die Reihenfolge zu ändern.</p>'}</section></div><section class="recommendation"><div class="recommend-icon">✓</div><div><span class="kicker">EMPFEHLUNG</span><h3>Heute ist keine Übernachtung sinnvoll.</h3><p>Die Heimfahrt dauert voraussichtlich 38 Minuten. Du bleibst damit innerhalb deiner Arbeitszeit.</p></div><button>Details</button></section>`)}
function round(){return shell(`${header('12-WOCHEN-ZEITRAUM','Deine Verkaufsrunde.')}<section class="simple"><div class="section-title"><div><span class="kicker">03. AUGUST – 25. OKTOBER</span><h2>25 von 25 Apotheken eingeplant</h2></div><button class="primary">✦ Runde optimieren</button></div><div class="week-grid">${[1,2,3,4].map((w,i)=>`<article><span>WOCHE ${w}</span><b>${i===0?'10':'5'} Besuche</b><small>${i===0?'Diese Woche':'Gut verteilt'}</small></article>`).join('')}</div><div class="timeline">${['Mo 03.','Di 04.','Mi 05.','Do 06.','Fr 07.'].map((d,i)=>`<div><b>${d}</b><span style="width:${[82,64,73,55,38][i]}%"></span><small>${[4,3,3,2,1][i]} Besuche</small></div>`).join('')}</div></section>`)}
function pharmacyView(){return shell(`${header('STAMMDATEN','Deine Apotheken.',`<button class="primary">＋ Apotheke</button>`)}<section class="simple"><input id="search" class="search" placeholder="Apotheke oder Ort suchen"><div id="pharmacy-list" class="pharmacy-list">${pharmacies.map(p=>pharmacyRow(p)).join('')}</div></section>`)}
function pharmacyRow(p){return `<article><span class="priority ${p.priority}">${p.priority}</span><div><b>${p.name}</b><small>${p.city}</small></div><label>Besuchszeit <select data-duration="${p.id}"><option ${p.duration===30?'selected':''}>30</option><option ${p.duration===45?'selected':''}>45</option><option ${p.duration===60?'selected':''}>60</option></select> Min.</label><a href="${nav(p)}" target="_blank" title="Navigation">⌖</a></article>`}
function settings(){return shell(`${header('PLANUNGSLOGIK','Deine Regeln.')}<section class="simple settings"><label>Startpunkt<input value="Niederdorfelden, 61138"></label><label>Arbeitsbeginn<input type="time" value="08:30"></label><label>Arbeitsende<input type="time" value="17:00"></label><label>Standard-Besuchsdauer<select><option>30 Minuten</option><option>45 Minuten</option></select></label><label>Übernachtungen<select><option>Automatisch empfehlen</option><option>Nie empfehlen</option></select></label></section>`)}
function render(){app.innerHTML=activeView==='today'?today():activeView==='round'?round():activeView==='pharmacies'?pharmacyView():settings();bind()}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;editing=false;render()});if(activeView==='today'){document.getElementById('edit').onclick=()=>{editing=!editing;render()};document.getElementById('optimize').onclick=()=>{route=[...route].sort((a,b)=>pharmacies.indexOf(byId(a))-pharmacies.indexOf(byId(b)));save();render()};if(editing){document.querySelectorAll('.stop').forEach(s=>{s.ondragstart=()=>s.classList.add('dragging');s.ondragend=()=>{s.classList.remove('dragging');route=[...document.querySelectorAll('.stop')].map(x=>x.dataset.id);save();render()};s.ondragover=e=>{e.preventDefault();const d=document.querySelector('.dragging');if(d&&d!==s)s.parentNode.insertBefore(d,e.clientY>s.getBoundingClientRect().top+s.offsetHeight/2?s.nextSibling:s)};s.querySelector('.remove').onclick=()=>{route=route.filter(id=>id!==s.dataset.id);save();render()}});document.getElementById('add').onclick=()=>{const p=pharmacies.find(p=>!route.includes(p.id));if(p){route.push(p.id);save();render()}}}}if(activeView==='pharmacies'){document.getElementById('search').oninput=e=>{document.getElementById('pharmacy-list').innerHTML=pharmacies.filter(p=>(p.name+p.city).toLowerCase().includes(e.target.value.toLowerCase())).map(pharmacyRow).join('')};document.querySelectorAll('[data-duration]').forEach(s=>s.onchange=()=>{byId(s.dataset.duration).duration=Number(s.value)})}}
render();
